_GROUP_POINTS = (
    "points=[[0,0,0],[0.25,0,0],[0.5,0,0],[0.75,0,0],[1,0,0],[0,1,0],"
    "[0.25,1,0],[0.5,1,0],[0.75,1,0],[1,1,0],[0,0.25,0],[0,0.5,0],"
    "[0,0.75,0],[1,0.25,0],[1,0.5,0],[1,0.75,0]];"
)

_AWS_DIRECT_TMPL = (
    "sketch=0;outlineConnect=0;fontColor=#232F3E;gradientColor=none;"
    "fillColor={fill};strokeColor=none;dashed=0;"
    "verticalLabelPosition=bottom;verticalAlign=top;align=center;html=1;"
    "fontSize=12;fontStyle=0;aspect=fixed;pointerEvents=1;"
    "shape=mxgraph.aws4.{name};"
)

_AWS_RESICON_TMPL = (
    "sketch=0;" + _GROUP_POINTS + "outlineConnect=0;fontColor=#232F3E;"
    "fillColor={fill};strokeColor=#ffffff;dashed=0;"
    "verticalLabelPosition=bottom;verticalAlign=top;align=center;html=1;"
    "fontSize=12;fontStyle=0;aspect=fixed;pointerEvents=1;"
    "shape=mxgraph.aws4.resourceIcon;resIcon=mxgraph.aws4.{name};"
)

_AZURE_IMG_TMPL = (
    "shape=image;html=1;verticalLabelPosition=bottom;verticalAlign=top;"
    "imageAspect=0;aspect=fixed;image={path};"
)

_GCP_TMPL = (
    "sketch=0;html=1;aspect=fixed;strokeColor=none;shadow=0;align=center;"
    "fillColor={fill};verticalAlign=top;labelPosition=center;"
    "verticalLabelPosition=bottom;shape=mxgraph.gcp2.{name};"
)


def _match(rules_sorted, suffix):
    for entry in rules_sorted:
        if suffix.startswith(entry[0]):
            return entry
    return None


def _aws_rules():
    if not getattr(_match, "_aws_cache", None):
        _match._aws_cache = sorted(_AWS_RULES, key=lambda r: -len(r[0]))
    return _match._aws_cache


def _azure_rules():
    if not getattr(_match, "_az_cache", None):
        _match._az_cache = sorted(_AZURE_RULES, key=lambda r: -len(r[0]))
    return _match._az_cache


def _gcp_rules():
    if not getattr(_match, "_gcp_cache", None):
        _match._gcp_cache = sorted(_GCP_RULES, key=lambda r: -len(r[0]))
    return _match._gcp_cache


def aws_native_style(r_type):
    """Return an official mxgraph.aws4 style for a terraform type, or None."""
    t = r_type.lower()
    if t.startswith("aws_"):
        t = t[4:]
    elif t.startswith("aws"):
        t = t[3:]
    hit = _match(_aws_rules(), t)
    if hit is None:
        return None
    _, kind, name, color = hit
    if kind == "resicon":
        return _AWS_RESICON_TMPL.format(fill=color, name=name)
    return _AWS_DIRECT_TMPL.format(fill=color, name=name)


def azure_native_style(r_type):
    """Return an official Azure library image style, or None."""
    t = r_type.lower()
    for prefix in ("azurerm_", "azure_", "az_"):
        if t.startswith(prefix):
            t = t[len(prefix):]
            break
    hit = _match(_azure_rules(), t)
    if hit is None:
        return None
    _, path = hit
    return _AZURE_IMG_TMPL.format(path="img/lib/azure2/" + path + ".svg")


def gcp_native_style(r_type):
    """Return an official mxgraph.gcp2 stencil style, or None."""
    t = r_type.lower()
    if t.startswith("google_"):
        t = t[len("google_"):]
    elif t.startswith("gcp_"):
        t = t[len("gcp_"):]
    hit = _match(_gcp_rules(), t)
    if hit is None:
        return None
    _, name, fill = hit
    return _GCP_TMPL.format(name=name, fill=fill)


def native_style_for(r_type):
    """Best-effort native draw.io style for any cloud resource type."""
    t = r_type.lower()
    if t.startswith(("aws_", "aws")):
        return aws_native_style(t)
    if t.startswith(("azurerm_", "azure_", "az_")):
        return azure_native_style(t)
    if t.startswith(("google_", "gcp_")):
        return gcp_native_style(t)
    return None


def native_icon_size(r_type):
    """Preferred icon box size: resourceIcons are designed at 78px."""
    style = native_style_for(r_type)
    if style and "resourceIcon" in style:
        return 78
    return 48
